# Get the full symbol with demangling for the Finalizer frame and refine SGen worker
# Let's also check if pin_major_object is accurate for the finalizer
aarch64-linux-gnu-nm --defined-only -S /tmp/libmonosgen-2.0.so.dbg 2>/dev/null | sort | awk '{
  start = strtonum("0x"$1)
  size = strtonum("0x"$2)
  end = start + size
  if (start <= 0x2c1a40 && end > 0x2c1a40) print "0x2c1a40 -> "$4" (offset +"sprintf("0x%x", 0x2c1a40-start)")"
  if (start <= 0x2f4b20 && end > 0x2f4b20) print "0x2f4b20 -> "$4" (offset +"sprintf("0x%x", 0x2f4b20-start)")"
  if (start <= 0x2f4c84 && end > 0x2f4c84) print "0x2f4c84 -> "$4" (offset +"sprintf("0x%x", 0x2f4c84-start)")"
}' 2>/dev/null

# Also get the closest named function for sgen worker using nm
aarch64-linux-gnu-nm -n /tmp/libmonosgen-2.0.so.dbg 2>/dev/null | awk '
/^[0-9a-f]+ [TtWw]/ {
  addr = strtonum("0x"$1)
  if (addr <= 0x2f4b20) { prev1 = $3; prevaddr1 = addr }
  if (addr <= 0x2f4c84) { prev2 = $3; prevaddr2 = addr }
}
END {
  printf "0x2f4b20 in %s+0x%x\n", prev1, 0x2f4b20-prevaddr1
  printf "0x2f4c84 in %s+0x%x\n", prev2, 0x2f4c84-prevaddr2
}'

