arguments.command:
# These are in the .bss/.data section (label 'b'). They're dispatch table entries for the interpreter.
# The actual code would be in mono_interp_exec_method. Let me look at the .text section only
# These are likely branch targets within the interpreter main loop.
# Let's verify by checking if these are in the executable section
aarch64-linux-gnu-readelf -S /tmp/libmonosgen-2.0.so.dbg 2>/dev/null | grep -E "\.text|\.rodata" | head -5

# Let me check the section for 0x2f4b20
aarch64-linux-gnu-readelf -S /tmp/libmonosgen-2.0.so.dbg 2>/dev/null | awk '
/\[/ { 
  if (match($0, /PROGBITS/)) {
    split($0, a, " ")
    for(i=1;i<=NF;i++) {
      if ($i ~ /^[0-9a-f]{6,}$/ && prev ~ /^[0-9a-f]{6,}$/) {
        start = strtonum("0x"prev)
        size = strtonum("0x"$i)
        if (start <= 0x2f4b20 && start+size > 0x2f4b20) print "0x2f4b20 is in section at 0x"prev
      }
      prev = $i
    }
  }
}'

# Actually, let's just check what section 0x2f4b20 falls in
aarch64-linux-gnu-objdump -h /tmp/libmonosgen-2.0.so.dbg 2>/dev/null | awk '{
  if (NF >= 6 && $2 !~ /^\./) next
  if (NF >= 6) {
    size = strtonum("0x"$3)
    vma = strtonum("0x"$4)
    if (vma <= 0x2f4b20 && vma+size > 0x2f4b20) printf "0x2f4b20 is in section %s (vma 0x%x, size 0x%x)\n", $2, vma, size
  }
}'

